    o[32..40].copy_from_slice(&((v[4] >> 4) | (v[5] << 59)).to_le_bytes());
    o[40..48].copy_from_slice(&((v[5] >> 5) | (v[6] << 58)).to_le_bytes());
    o[48..56].copy_from_slice(&((v[6] >> 6) | (v[7] << 57)).to_le_bytes());
    o[56..64].copy_from_slice(&((v[7] >> 7) | (v[8] << 56)).to_le_bytes());
    o[64..72].copy_from_slice(&((v[8] >> 8) | (v[9] << 55)).to_le_bytes());
    o[72..80].copy_from_slice(&((v[9] >> 9) | (v[10] << 54)).to_le_bytes());
    o[80..88].copy_from_slice(&((v[10] >> 10) | (v[11] << 53)).to_le_bytes());
    o[88..96].copy_from_slice(&((v[11] >> 11) | (v[12] << 52)).to_le_bytes());
    o[96..104].copy_from_slice(&((v[12] >> 12) | (v[13] << 51)).to_le_bytes());
    o[104..112].copy_from_slice(&((v[13] >> 13) | (v[14] << 50)).to_le_bytes());
    o[112..120].copy_from_slice(&((v[14] >> 14) | (v[15] << 49)).to_le_bytes());
    o[120..128].copy_from_slice(&((v[15] >> 15) | (v[16] << 48)).to_le_bytes());
