    o[144..152].copy_from_slice(&((v[18] >> 18) | (v[19] << 45)).to_le_bytes());
    o[152..160].copy_from_slice(&((v[19] >> 19) | (v[20] << 44)).to_le_bytes());
    o[160..168].copy_from_slice(&((v[20] >> 20) | (v[21] << 43)).to_le_bytes());
    o[168..176].copy_from_slice(&((v[21] >> 21) | (v[22] << 42)).to_le_bytes());
    o[176..184].copy_from_slice(&((v[22] >> 22) | (v[23] << 41)).to_le_bytes());
    o[184..192].copy_from_slice(&((v[23] >> 23) | (v[24] << 40)).to_le_bytes());
    o[192..200].copy_from_slice(&((v[24] >> 24) | (v[25] << 39)).to_le_bytes());
    o[200..208].copy_from_slice(&((v[25] >> 25) | (v[26] << 38)).to_le_bytes());
    o[208..216].copy_from_slice(&((v[26] >> 26) | (v[27] << 37)).to_le_bytes());
